import React from 'react';
import { useParams, useNavigate } from 'react-router-dom'; // أضفنا useParams لجلب معرف العرض
import { Building2, MapPin, Calendar, ArrowRight } from 'lucide-react';

const OfferDetails = () => {
  const { id } = useParams(); // استخراج المعرف من الرابط
  const navigate = useNavigate();

  const offerData = {
    title: "مطور ويب React",
    company: "Tech Solutions",
    location: "قسنطينة",
    description: "نحن نبحث عن متربص شغوف بتعلم تطوير الواجهات الأمامية باستخدام React و Tailwind CSS...",
    duration: "3 أشهر",
    postedAt: "منذ يومين"
  };

  // الدالة المسؤولة عن تشغيل زر التقديم
  const handleApply = () => {
    alert(` إرسال طلبك بنجاح للعرض رقم: ${id}`);
    // يمكنك هنا إضافة كود لإرسال البيانات إلى السيرفر لاحقاً
  };

  return (
    <div className="max-w-4xl mx-auto" dir="rtl">
      <button 
        onClick={() => navigate(-1)} 
        className="flex items-center gap-2 text-slate-500 hover:text-blue-600 mb-6 transition-colors"
      >
        <ArrowRight size={20} /> رجوع للback
      </button>

      <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
        <div className="flex items-start justify-between mb-8">
          <div className="flex gap-4">
            <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center">
              <Building2 size={32} />
            </div>
            <div>
              <h1 className="text-2xl font-black text-slate-900">{offerData.title}</h1>
              <p className="text-blue-600 font-bold">{offerData.company}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-8">
          <div className="flex items-center gap-2 text-slate-500 bg-slate-50 p-4 rounded-xl">
            <MapPin size={18} /> {offerData.location}
          </div>
          <div className="flex items-center gap-2 text-slate-500 bg-slate-50 p-4 rounded-xl">
            <Calendar size={18} /> {offerData.duration}
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold">وصف التربص</h2>
          <p className="text-slate-600 leading-relaxed">{offerData.description}</p>
        </div>

        {/* ربط الدالة بالزر هنا */}
        <button 
          onClick={handleApply}
          className="w-full mt-10 py-4 bg-blue-600 text-white rounded-2xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all"
        >
          تقديم الطلب الآن
        </button>
      </div>
    </div>
  );
};

export default OfferDetails;
